    /**
     * Tests getting all TypeCertificates.
     *
     * @return    Collection
     */
    public List<TypeCertificate> testGetAll() throws Throwable {
    LOGGER.info( "TypeCertificateTest:testGetAll() - Retrieving Collection of TypeCertificates:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all TypeCertificate : " );
    List<TypeCertificate> collection  = null;

    try {
        // call the static get method on the TypeCertificateService
        collection = service.getAllTypeCertificate();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            TypeCertificate currEntity  = null;
            Iterator<TypeCertificate> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getTypeCertificateId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

